// ---------- helpers ----------
function safeLog2(x) {
  return x <= 0 ? 0 : Math.log2(x);
}

// Normalize weights into a probability vector; fall back to uniform if all zero.
function normalizeWeights(w) {
  const n = w.length;
  let s = 0;
  for (let i = 0; i < n; i++) {
    const v = Number(w[i]);
    s += (isFinite(v) && v > 0) ? v : 0;
  }
  if (s <= 0) {
    return L.range(n).map(() => 1 / n);
  }
  return w.map(v => {
    const x = Number(v);
    return (isFinite(x) && x > 0) ? x / s : 0;
  });
}

// ---------- compute ----------
function compute(s) {
  const n = Math.max(1, Math.min(6, Math.round(Number(s.n) || 1)));
  let w = Array.isArray(s.w) ? s.w.slice(0, n) : [];
  while (w.length < n) w.push(0);
  w = w.map(v => {
    const x = Number(v);
    return (isFinite(x) && x > 0) ? x : 0;
  });

  const p = normalizeWeights(w);
  const contrib = p.map(pi => (pi <= 0 ? 0 : -pi * safeLog2(pi)));
  let H = 0;
  for (let i = 0; i < contrib.length; i++) H += contrib[i];
  if (!isFinite(H)) H = 0;

  const log2n = safeLog2(n);
  const uniform = p.map(() => 1 / n);
  const uniformContrib = uniform.map(pi => -pi * safeLog2(pi));

  // how far from uniform (max |p_i - 1/n|)
  let dev = 0;
  for (let i = 0; i < n; i++) dev = Math.max(dev, Math.abs(p[i] - 1 / n));

  const maxContribIdx = L.argmax(contrib);
  const sumP = L.sum(p);

  return {
    n: n,
    w: w,
    p: p,
    contrib: contrib,
    H: H,
    log2n: log2n,
    uniform: uniform,
    uniformContrib: uniformContrib,
    dev: dev,
    maxContribIdx: maxContribIdx,
    sumP: sumP,
    isUniform: dev < 1e-9,
    isCertain: p.some(pi => pi > 1 - 1e-9)
  };
}

// ---------- render ----------
function render(s, r) {
  const w = 740, h = 360;
  const n = r.n;
  const padL = 60, padR = 20, padT = 46, padB = 60;
  const gap = 34;
  const panelW = (w - padL - padR - gap) / 2;
  const panelH = h - padT - padB;

  const leftX = padL, rightX = padL + panelW + gap;
  const topY = padT;

  const colors = L.range(n).map(i => L.color(i));

  // ---- left panel: probabilities ----
  const maxP = Math.max(1 / n, L.max(r.p), 1e-9);
  const leftBars = L.bars({
    x: leftX, y: topY, w: panelW, h: panelH,
    values: r.p,
    labels: L.range(n).map(i => "p" + (i + 1)),
    title: "probabilities $p_i$",
    yLabel: "probability",
    min: 0, max: maxP,
    colors: colors,
    highlight: r.maxContribIdx,
    fmt: v => L.fmt(v, 3),
    refLines: [{ value: 1 / n, label: "1/n = " + L.fmt(1 / n, 3) }]
  });

  // ---- right panel: contributions ----
  const maxC = Math.max(L.max(r.contrib), L.max(r.uniformContrib), 1e-9);
  const rightBars = L.bars({
    x: rightX, y: topY, w: panelW, h: panelH,
    values: r.contrib,
    labels: L.range(n).map(i => "-p" + (i + 1) + " log2 p" + (i + 1)),
    title: "contributions $-p_i \\log_2 p_i$",
    yLabel: "bits",
    min: 0, max: maxC,
    colors: colors.map(c => "#2e8b57"),
    highlight: r.maxContribIdx,
    fmt: v => L.fmt(v, 3),
    refLines: [{ value: r.log2n, label: "log2 n = " + L.fmt(r.log2n, 3) }]
  });

  // ---- header text ----
  const head = L.text(w / 2, 22,
    "H = " + L.fmt(r.H, 4) + " bits    |    log2 n = " + L.fmt(r.log2n, 4) + " bits    |    n = " + n,
    { size: 15, anchor: "middle", weight: "bold", color: "#1a1a1a" });

  const foot = L.text(w / 2, h - 16,
    "sum p_i = " + L.fmt(r.sumP, 4) + "    |    sum of contributions = " + L.fmt(L.sum(r.contrib), 4),
    { size: 13, anchor: "middle", color: "#444" });

  return L.svg(w, h, head + leftBars + rightBars + foot);
}

// ---------- show ----------
function show(s, r) {
  const n = r.n;
  const rows = [];
  rows.push({
    label: "number of outcomes n",
    value: n,
    digits: 0,
    note: "length of the probability vector"
  });
  rows.push({
    label: "probabilities p_i",
    value: r.p,
    digits: 4,
    note: "weights normalized so they sum to 1",
    colLabels: L.range(n).map(i => "p" + (i + 1))
  });
  rows.push({
    label: "contributions -p_i log2 p_i",
    value: r.contrib,
    digits: 4,
    note: "each outcome's share of the entropy, in bits",
    colLabels: L.range(n).map(i => "c" + (i + 1)),
    highlight: r.maxContribIdx
  });
  rows.push({
    label: "total entropy H",
    value: r.H,
    digits: 4,
    note: "sum of the contributions; 0 bits means certainty",
    highlight: 0
  });
  rows.push({
    label: "uniform reference log2 n",
    value: r.log2n,
    digits: 4,
    note: "maximum possible H for this n"
  });
  rows.push({
    label: "max |p_i - 1/n|",
    value: r.dev,
    digits: 4,
    note: "0 exactly when the distribution is uniform"
  });
  return rows;
}

// ---------- checks ----------
function checks(s, r) {
  const out = [];
  const n = r.n;

  out.push({
    name: "probabilities sum to 1",
    pass: Math.abs(r.sumP - 1) < 1e-9,
    detail: "sum p_i = " + L.fmt(r.sumP, 6)
  });

  out.push({
    name: "H >= 0",
    pass: r.H >= -1e-9,
    detail: "H = " + L.fmt(r.H, 6) + " bits"
  });

  out.push({
    name: "H = 0 iff exactly one p_i = 1",
    pass: (Math.abs(r.H) < 1e-9) === r.isCertain,
    detail: "H = " + L.fmt(r.H, 6) + ", certain = " + r.isCertain
  });

  out.push({
    name: "H <= log2 n, equality iff uniform",
    pass: (r.H <= r.log2n + 1e-9) && ((Math.abs(r.H - r.log2n) < 1e-9) === r.isUniform),
    detail: "H = " + L.fmt(r.H, 6) + ", log2 n = " + L.fmt(r.log2n, 6) + ", uniform = " + r.isUniform
  });

  out.push({
    name: "sum of contributions equals H",
    pass: Math.abs(L.sum(r.contrib) - r.H) < 1e-9,
    detail: "sum c_i = " + L.fmt(L.sum(r.contrib), 6) + ", H = " + L.fmt(r.H, 6)
  });

  let zeroOk = true;
  for (let i = 0; i < n; i++) {
    if (r.p[i] <= 0 && Math.abs(r.contrib[i]) > 1e-12) zeroOk = false;
  }
  out.push({
    name: "zero probabilities contribute exactly 0",
    pass: zeroOk,
    detail: "0 log2 0 treated as 0"
  });

  return out;
}
